<?php
declare(strict_types=1);
require __DIR__.'/shipping_typed.php';
use Shipping\Rules;
$c=shippingSubmit(['action'=>'create','customer'=>'CARRIER-FAILURE','destination'=>'CUSTOMER-A','lines'=>[['sku'=>'PRODUCT','quantity'=>2],['sku'=>'WIDGET','quantity'=>1]]]);typedUntil('new',$c['id']);shippingSubmit(['action'=>'fulfil','reference'=>$c['id']]);typedUntil('ready',$c['id']);shippingSubmit(['action'=>'pack','reference'=>$c['id']]);typedUntil('packed',$c['id']);shippingSubmit(['action'=>'dispatch','reference'=>$c['id']]);typedUntil('awaiting_carrier',$c['id']);
$o=$shipping->order($c['id']);$legs=array_values(array_filter($o['intents'],fn($i)=>$i['kind']==='dispatch'));$r=$ledger->status()['run'];
function carrierFact(array $o,array $i,string $result,float $due):array {global $r;foreach($o['lines'] as $l)if($l['id']===$i['line_id'])$line=$l;return ['schema_version'=>'1.0','type'=>'shipping.fact.v1','event_id'=>Rules::uuid4(),'federation_id'=>'typed-test','run_id'=>$r['id'],'epoch'=>$r['epoch'],'correlation_id'=>$o['correlation_id'],'causation_id'=>$i['id'],'aggregate_id'=>$i['kind']==='deliver'?$o['shipment']['id']:$o['id'],'aggregate_version'=>1,'source'=>'logistics','destination'=>'shipping','boundary'=>'carrier','effective_time'=>$due,'quantity_unit'=>'item','payload'=>['intent_id'=>$i['id'],'owner'=>'logistics','result'=>$result,'reference'=>$i['kind']==='deliver'?$o['shipment']['id']:$o['id'],'sku'=>$line['sku'],'quantity'=>$line['quantity'],'destination'=>$o['destination']]];}
function failureAdvance():void {global $db,$ledger;$r=$ledger->status()['run'];$db->transaction(fn($u)=>$u->execute('UPDATE boundary_outbox SET sent_at=clock_timestamp() WHERE run_id=?',[$r['id']]));$jobs=$db->transaction(fn($u)=>$u->query("SELECT * FROM jobs WHERE run_id=? AND status='pending' ORDER BY due_at,id",[$r['id']]));$time=(float)$jobs[0]['due_at'];shippingCheck($ledger->prepare($time,$r['epoch']),'failure case time barrier settles');$ledger->grant($time,$r['epoch']);$ledger->heartbeat('controller');foreach($jobs as $j)if($j['due_at']<=$time)$ledger->execute($j['id']);}
$failure=carrierFact($o,$legs[0],'failed',$r['granted']+1);shippingCheck($shipping->ingest($failure,'logistics/events')==='accepted','carrier may report its own explicit failure');
$shipping->ingest(carrierFact($o,$legs[1],'departed',$r['granted']+1),'logistics/events');failureAdvance();$o=$shipping->order($o['id']);shippingCheck($o['status']==='blocked','one failed leg cannot be hidden by another departure');
$delivery=array_values(array_filter($o['intents'],fn($i)=>$i['kind']==='deliver'))[0];$r=$ledger->status()['run'];$shipping->ingest(carrierFact($o,$delivery,'delivered',$r['granted']+1),'logistics/events');failureAdvance();$o=$shipping->order($o['id']);shippingCheck($o['status']==='blocked'&&$o['shipment']['status']==='blocked'&&$o['shipment']['confirmation_id']===null,'successful leg cannot deliver a shipment with a failed leg');
echo "Shipping explicit carrier failure checks passed\n";
